const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x) = F₀(1 − x/h)' },
      { kind: 'text', payload: 'F' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'F₀' },
      { kind: 'text', payload: 'F₀/2' },
      { kind: 'text', payload: 'S' },
      { kind: 'text', payload: 'S = 3/8 F₀h = 0.375 F₀h' }
    ];
  },
  render: function (input, metrics) {
    var vp = (input && input.viewport) ? input.viewport : {};
    var W = Number(vp.widthDu) || 680;
    var H = Number(vp.heightDu) || 440;
    var rev = (input && input.revision !== undefined && input.revision !== null) ? input.revision : 1;

    var padL = 86, padR = 60, padT = 66, padB = 80;
    var x0 = padL;
    var y0 = H - padB;
    var yF0 = padT + 26;
    var xEnd = x0 + 0.9 * ((W - padR) - x0);

    var xP = function (v) { return x0 + v * (xEnd - x0); };
    var yF = function (v) { return y0 - v * (y0 - yF0); };

    var paths = [];
    var nodes = [];
    function addPath(id, cmds, style) {
      paths.push({ id: id, commands: cmds });
      var n = { type: 'path', pathId: id };
      if (style) {
        for (var k in style) {
          if (Object.prototype.hasOwnProperty.call(style, k)) { n[k] = style[k]; }
        }
      }
      nodes.push(n);
    }
    function addLabel(text, x, y, opts) {
      var n = { type: 'label', text: text, x: x, y: y, fontSize: 14, fill: '#1b2a3a', textAnchor: 'start' };
      if (opts) {
        for (var k in opts) {
          if (Object.prototype.hasOwnProperty.call(opts, k)) { n[k] = opts[k]; }
        }
      }
      nodes.push(n);
    }

    var curvePts = [];
    var N = 64;
    for (var i = 0; i <= N; i++) {
      var t = i / N;
      curvePts.push([xP(t), yF(1 - t)]);
    }

    addPath('shade', visualSdk.polyline([
      [xP(0), y0], [xP(0.5), y0], [xP(0.5), yF(0.5)], [xP(0), yF(1)], [xP(0), y0]
    ]), { fill: '#a9cbea', stroke: '#6f9dcb', strokeWidth: 1.2 });

    addPath('guide', visualSdk.polyline([[x0, yF(0.5)], [xP(0.5), yF(0.5)]]), { stroke: '#8a97a6', strokeWidth: 1.1, strokeDasharray: [6, 4], fill: 'none' });

    addPath('xaxis', visualSdk.polyline([[x0 - 26, y0], [xEnd + 30, y0]]), { stroke: '#26354a', strokeWidth: 1.6, fill: 'none' });
    addPath('xarrow', visualSdk.arrow(xEnd + 12, y0, xEnd + 34, y0), { stroke: '#26354a', strokeWidth: 1.6, fill: '#26354a' });
    addPath('yaxis', visualSdk.polyline([[x0, y0 + 26], [x0, yF0 - 32]]), { stroke: '#26354a', strokeWidth: 1.6, fill: 'none' });
    addPath('yarrow', visualSdk.arrow(x0, yF0 - 12, x0, yF0 - 40), { stroke: '#26354a', strokeWidth: 1.6, fill: '#26354a' });

    addPath('tickHalf', visualSdk.polyline([[xP(0.5), y0 - 5], [xP(0.5), y0 + 5]]), { stroke: '#26354a', strokeWidth: 1.4, fill: 'none' });
    addPath('tickH', visualSdk.polyline([[xP(1), y0 - 5], [xP(1), y0 + 5]]), { stroke: '#26354a', strokeWidth: 1.4, fill: 'none' });
    addPath('tickF0', visualSdk.polyline([[x0 - 5, yF(1)], [x0, yF(1)]]), { stroke: '#26354a', strokeWidth: 1.4, fill: 'none' });
    addPath('tickHalfF', visualSdk.polyline([[x0 - 5, yF(0.5)], [x0, yF(0.5)]]), { stroke: '#26354a', strokeWidth: 1.4, fill: 'none' });

    addPath('curve', visualSdk.polyline(curvePts), { stroke: '#1f4e79', strokeWidth: 2.6, fill: 'none' });
    addPath('dotHalf', visualSdk.circle(xP(0.5), yF(0.5), 4), { fill: '#1f4e79', stroke: '#1f4e79', strokeWidth: 1 });

    addPath('leader', visualSdk.polyline([[xP(0.30), yF(0.42)], [xP(0.54), yF(0.86)]]), { stroke: '#2b5f8f', strokeWidth: 1.1, strokeDasharray: [4, 3], fill: 'none' });

    addLabel('F(x) = F₀(1 − x/h)', 14, 28, { fontSize: 16, fill: '#12283d' });
    addLabel('F', x0 - 14, yF0 - 44, { fontSize: 16, textAnchor: 'end' });
    addLabel('x', xEnd + 40, y0 + 20, { fontSize: 16 });
    addLabel('0', x0 - 12, y0 + 20, { fontSize: 14 });
    addLabel('h/2', xP(0.5), y0 + 22, { fontSize: 14, textAnchor: 'middle' });
    addLabel('h', xP(1), y0 + 22, { fontSize: 14, textAnchor: 'middle' });
    addLabel('F₀', x0 - 10, yF(1) + 5, { fontSize: 14, textAnchor: 'end' });
    addLabel('F₀/2', x0 - 10, yF(0.5) + 5, { fontSize: 14, textAnchor: 'end' });
    addLabel('S', xP(0.20), yF(0.30), { fontSize: 17, textAnchor: 'middle', fill: '#2b5f8f' });
    addLabel('S = 3/8 F₀h = 0.375 F₀h', xP(0.56), yF(0.90), { fontSize: 14, fill: '#2b5f8f' });

    return {
      schemaVersion: 1,
      sceneId: 'fig-fx-linear-shade-area',
      revision: rev,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
